    private async Task ViewHistoryEntryAsync(string id)
    {
        selectedHistoryEntry = await LocalCoderHistoryService.GetEntryAsync(id);
        contextRestoreResult = null;
    }

    private async Task RestoreHistoryContextAsync()
    {
        if (selectedHistoryEntry is null)
        {
            return;
        }

        if (selectedHistoryEntry.ContextFiles.Count == 0)
        {
            NotificationService.Notify(
                NotificationSeverity.Info,
                "No context snapshot",
                "This history entry has no saved context snapshot.");
            return;
        }

        if (isContextLocked)
        {
            NotificationService.Notify(NotificationSeverity.Warning, "Context locked", "Unlock context before restoring history.");
            return;
        }

        if (selectedFilePaths.Count > 0 || fileContexts.Count > 0)
        {
            var confirmed = await DialogService.Confirm(
                "Replace the current file context with the saved history context?",
                "Restore Context",
                new ConfirmOptions { OkButtonText = "Restore Context", CancelButtonText = "Cancel" });

            if (confirmed != true)
            {
                return;
            }
        }

        request.ProjectPath = selectedHistoryEntry.ProjectPath;
        contextRestoreResult = await LocalCoderContextService.RestoreAsync(
            request.ProjectPath,
            selectedHistoryEntry.ContextFiles);

        ClearLoadedContext();
        fileContexts = contextRestoreResult.RestoredContexts.ToList();
        request.FileContexts = fileContexts.ToList();
        selectedFilePaths = fileContexts.Select(file => file.RelativePath).ToList();
        selectedFiles = fileContexts
            .Select(file => new FileSearchItem
            {
                FileName = Path.GetFileName(file.RelativePath),
                FullPath = file.FullPath,
                RelativePath = file.RelativePath,
                Extension = Path.GetExtension(file.RelativePath),
                SizeBytes = new System.IO.FileInfo(file.FullPath).Length
            })
            .ToList();

        NotificationService.Notify(
            NotificationSeverity.Success,
            "Context restore complete",
            $"{fileContexts.Count} file(s) restored from history.");
    }

    private async Task UseHistoryEntryAsContextAsync()
    {
        if (selectedHistoryEntry is null)
        {
            return;
        }

        request.ProjectPath = selectedHistoryEntry.ProjectPath;
        if (!string.IsNullOrWhiteSpace(selectedHistoryEntry.Model))
        {
            request.Model = selectedHistoryEntry.Model;
        }

        selectedFilePaths = selectedHistoryEntry.SelectedFiles.ToList();
        selectedFiles = selectedFilePaths
            .Select(relativePath => new FileSearchItem
            {
                FileName = Path.GetFileName(relativePath),
                FullPath = Path.Combine(request.ProjectPath, relativePath),
                RelativePath = relativePath,
                Extension = Path.GetExtension(relativePath)
            })
            .ToList();
        ClearLoadedContext();

        await EnsureFileContextLoadedAsync();

        var summary = BuildHistoryContextSummary(selectedHistoryEntry);
        request.Task = string.IsNullOrWhiteSpace(request.Task)
            ? summary
            : $"{request.Task.TrimEnd()}{Environment.NewLine}{Environment.NewLine}{summary}";

        NotificationService.Notify(
            NotificationSeverity.Success,
            "History context loaded",
            "The history entry was loaded into the current task context.");
    }

    private async Task ClearHistoryAsync()
    {
        var confirmed = await DialogService.Confirm(
            "Clear all Local Coder history entries?",
            "Clear History",
            new ConfirmOptions { OkButtonText = "Clear History", CancelButtonText = "Cancel" });

        if (confirmed != true)
        {
            return;
        }

        isClearingHistory = true;

        try
        {
            await LocalCoderHistoryService.ClearHistoryAsync();
            historyEntries = [];
            selectedHistoryEntry = null;

            NotificationService.Notify(
                NotificationSeverity.Success,
                "History cleared",
                "Local Coder history was cleared.");
        }
        catch (Exception exception)
        {
            error = exception.Message;

            NotificationService.Notify(
                NotificationSeverity.Error,
                "History clear failed",
                exception.Message);
        }
        finally
        {
            isClearingHistory = false;
        }
    }

    private async Task SaveHistoryEntryAsync(
        LocalCoderHistoryActionType actionType,
        bool success,
        string message,
        string? planText = null,
        string? patchPreviewText = null,
        LocalCoderPatchApplyResult? applyResult = null,
        LocalCoderPatchRollbackResult? rollbackResult = null,
        IReadOnlyList<CommandRunResult>? verificationResults = null,
        string? model = null,
        IReadOnlyList<LocalCoderHistoryContextFile>? contextSnapshot = null,
        string? taskTextOverride = null,
        IReadOnlyList<LocalCoderPlanTask>? planTasksSnapshot = null)
    {
        try
        {
            contextSnapshot ??= CreateContextSnapshot(actionType);

            await LocalCoderHistoryService.AddEntryAsync(new LocalCoderHistoryEntry
            {
                ActionType = actionType,
                CreatedAt = DateTimeOffset.UtcNow,
                ProjectPath = request.ProjectPath,
                Model = model ?? request.Model,
                Task = taskTextOverride ?? request.Task,
                SelectedFiles = selectedFilePaths.ToArray(),
                LoadedContextFiles = request.FileContexts
                    .Select(fileContext => new LocalCoderHistoryFileSummary
                    {
                        RelativePath = fileContext.RelativePath,
                        CharacterCount = fileContext.CharacterCount
                    })
                    .ToArray(),
                ContextFileCount = contextSnapshot.Count,
                ContextTotalCharacters = contextSnapshot.Sum(file => file.CharacterCount),
                ContextEstimatedTokens = contextSnapshot.Sum(file => file.EstimatedTokens),
                ContextFiles = contextSnapshot,
                PlanTasks = (planTasksSnapshot ?? GetPlanTasksSnapshot()).ToArray(),
                PlanText = planText ?? string.Empty,
                PatchPreviewText = patchPreviewText ?? string.Empty,
                ApplyResult = applyResult,
                RollbackResult = rollbackResult,
                VerificationResults = verificationResults?.ToArray() ?? [],
                Success = success,
                Message = message
            });

            await LoadHistoryAsync();
        }
        catch (Exception exception)
        {
            Console.WriteLine($"History save failed: {exception}");
            NotificationService.Notify(
                NotificationSeverity.Warning,
                "History save failed",
                "Local Coder could not save history right now. The current run continues, but this entry was not persisted.");
        }
    }

    private IReadOnlyList<LocalCoderHistoryContextFile> CreateContextSnapshot(LocalCoderHistoryActionType actionType)
    {
        if (request.FileContexts.Count == 0
            || actionType is not (LocalCoderHistoryActionType.CreatePlan
                or LocalCoderHistoryActionType.GeneratePatchPreview
                or LocalCoderHistoryActionType.VerifyProject))
        {
            return [];
        }

        return request.FileContexts
            .Select(file => new LocalCoderHistoryContextFile
            {
                RelativePath = file.RelativePath,
                CharacterCount = file.CharacterCount,
                EstimatedTokens = file.EstimatedTokens,
                ContentHash = Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(file.Content)))
                    .ToLowerInvariant()
            })
            .ToArray();
    }

    private void ClearPlanTasks()
    {
        planTasks.Clear();
        selectedPlanTaskId = null;
        activePlanTaskId = null;
    }

    private void InitializePlanTasks(string planText)
    {
        planTasks.Clear();
        planTasks.AddRange(BuildPlanTasks(planText));
        selectedPlanTaskId = planTasks.FirstOrDefault()?.Id;
        activePlanTaskId = null;
    }

    private Task OnSelectedPlanTaskChangedAsync(string? planTaskId)
    {
        selectedPlanTaskId = planTaskId;
        return Task.CompletedTask;
    }

    private bool CanExecuteSelectedPlanTask()
    {
        return !isGeneratingPatch &&
               !isApplyingPatch &&
               planTasks.Count > 0 &&
               !string.IsNullOrWhiteSpace(selectedPlanTaskId) &&
               planTasks.Any(task => task.Id == selectedPlanTaskId);
    }

    private bool CanExecuteNextPlanTask()
    {
        return !isGeneratingPatch &&
               !isApplyingPatch &&
               planTasks.Any(task => task.Status == LocalCoderPlanTaskStatus.Pending);
    }

    private IReadOnlyList<LocalCoderPlanTask> GetPlanTasksSnapshot()
    {
        return planTasks
            .OrderBy(task => task.Order)
            .Select(task => new LocalCoderPlanTask
            {
                Id = task.Id,
                Order = task.Order,
                Title = task.Title,
                Description = task.Description,
                Status = task.Status,
                StatusMessage = task.StatusMessage,
                UpdatedAt = task.UpdatedAt
            })
            .ToArray();
    }

    private void UpdatePlanTaskStatus(string planTaskId, LocalCoderPlanTaskStatus status, string? statusMessage = null)
    {
        var task = planTasks.FirstOrDefault(item => item.Id == planTaskId);
        if (task is null)
        {
            return;
        }

        task.Status = status;
        task.StatusMessage = statusMessage ?? string.Empty;
        task.UpdatedAt = DateTimeOffset.UtcNow;
    }

    private string? GetActivePlanTaskText()
    {
        if (string.IsNullOrWhiteSpace(activePlanTaskId))
        {
            return null;
        }

        var task = planTasks.FirstOrDefault(item => item.Id == activePlanTaskId);
        return task is null ? null : BuildPlanTaskTaskText(task);
    }

    private static LocalCoderRequest CloneRequest(LocalCoderRequest source, string taskText)
    {
        return new LocalCoderRequest
        {
            ProjectPath = source.ProjectPath,
            Model = source.Model,
            Task = taskText,
            FileContexts = source.FileContexts.Select(file => new LocalCoderFileContext
            {
                RelativePath = file.RelativePath,
                FullPath = file.FullPath,
                Content = file.Content,
                IsGeneratedFile = file.IsGeneratedFile
            }).ToList(),
            AllowedPatchScope = source.AllowedPatchScope,
            AllowedPatchFolders = source.AllowedPatchFolders.ToList()
        };
    }

    private static List<LocalCoderPlanTask> BuildPlanTasks(string planText)
    {
        var tasks = new List<LocalCoderPlanTask>();
        var lines = (planText ?? string.Empty)
            .ReplaceLineEndings("\n")
            .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);

        var order = 1;
        foreach (var line in lines)
        {
            var trimmed = line.Trim();
            var match = System.Text.RegularExpressions.Regex.Match(trimmed, @"^(?:[-*]\s+|\d+[.)]\s+)(.+)$");
            if (!match.Success)
            {
                continue;
            }

            var description = match.Groups[1].Value.Trim();
            if (string.IsNullOrWhiteSpace(description))
            {
                continue;
            }

            tasks.Add(new LocalCoderPlanTask
            {
                Order = order++,
                Title = $"Task {order - 1}",
                Description = description,
                Status = LocalCoderPlanTaskStatus.Pending
            });
        }

        if (tasks.Count == 0 && !string.IsNullOrWhiteSpace(planText))
        {
            tasks.Add(new LocalCoderPlanTask
            {
                Order = 1,
                Title = "Task 1",
                Description = planText.Trim(),
                Status = LocalCoderPlanTaskStatus.Pending
            });
        }

        return tasks;
    }

    private static string BuildPlanTaskTaskText(LocalCoderPlanTask task)
    {
        return string.IsNullOrWhiteSpace(task.Description) ? task.Title : task.Description;
    }

